CREATE OR REPLACE FUNCTION public.home_entity(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entity jsonb; published jsonb;
begin
 entity:=public.seo_entity(p_slug);
 if entity is null or entity->>'id' is null then return entity;end if;
 if not exists(select 1 from zoi.listings where id=(entity->>'id')::uuid and publish_status='published' and moderation_status in ('clean','cleared') and coalesce(marketplace_status,'')<>'hidden') then return null;end if;
 published:=public.home_design_public((entity->>'id')::uuid);
 return entity||jsonb_build_object('published_design',published);
end $function$

CREATE OR REPLACE FUNCTION zoi.enrich_apply(p_batch jsonb)
 RETURNS TABLE(slug text, applied boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb;l zoi.listings;machine jsonb;incoming jsonb;lease jsonb;
BEGIN
 IF jsonb_typeof(p_batch) IS DISTINCT FROM 'array' OR jsonb_array_length(p_batch)>200 OR octet_length(p_batch::text)>2000000 THEN RAISE EXCEPTION 'invalid_enrichment_batch';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_batch) LOOP
  SELECT * INTO l FROM zoi.listings WHERE listings.slug=r->>'slug' FOR UPDATE;
  lease:=l.profile->'_enrich'->'lease';
  IF l.id IS NULL OR l.publish_status IS DISTINCT FROM 'published' OR l.moderation_status NOT IN('clean','cleared') OR l.moderation_status IS NULL OR coalesce(l.marketplace_status,'')='hidden' OR lease->>'task' IS DISTINCT FROM 'enrichment' OR lease->>'fingerprint' IS DISTINCT FROM zoi.listing_quality_fingerprint(l) OR lease->>'authority_version' IS DISTINCT FROM '1' OR lease->>'authority_fingerprint' IS DISTINCT FROM zoi.enrich_authority_fingerprint(l) OR nullif(r->>'lease_id','') IS NULL OR (lease->>'id') IS DISTINCT FROM (r->>'lease_id') OR (lease->>'source_website') IS DISTINCT FROM l.website OR coalesce(zoi.enrich_timestamp(lease->>'expires_at'),'-infinity')<=clock_timestamp() THEN
   RETURN QUERY SELECT r->>'slug',false;CONTINUE;
  END IF;
  incoming:=coalesce(r->'profile','{}');
  IF jsonb_typeof(incoming) IS DISTINCT FROM 'object' OR jsonb_typeof(coalesce(r->'provenance','{}')) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid_enrichment_fields';END IF;
  IF (incoming->>'crawl_status'='error' OR incoming->>'blocked'='true') THEN
   machine:=(coalesce(l.profile->'_enrich','{}')-'lease')||jsonb_build_object('crawl_status','error','status','error','last_error',left(coalesce(incoming->>'last_error','crawl_failed'),200),'last_attempt_at',clock_timestamp()) || CASE WHEN incoming->>'blocked'='true' THEN jsonb_build_object('blocked','true','blocked_reason',left(coalesce(nullif(incoming->>'blocked_reason',''),'source_blocked'),200)) ELSE '{}'::jsonb END;
  ELSE
   machine:=(zoi.profile_strip(incoming)-'lease')||jsonb_build_object('provenance',coalesce(r->'provenance','{}'),'source_url',r->>'website','checked_at',to_char(now(),'YYYY-MM-DD'),'last_attempt_at',clock_timestamp(),'status',coalesce(incoming->>'crawl_status','ok'));
  END IF;
  UPDATE zoi.listings SET profile=coalesce(l.profile,'{}')||jsonb_build_object('_enrich',machine,'_coverage',jsonb_set(CASE WHEN (incoming->>'crawl_status'='error' OR incoming->>'blocked'='true') THEN zoi.listing_quality_state(l) ELSE jsonb_set(jsonb_set(jsonb_set(zoi.listing_quality_state(l),'{tasks,classification}','{"status":"pending"}'),'{tasks,design}','{"status":"pending"}'),'{tasks,verification}','{"status":"pending"}') END,'{tasks,enrichment}',jsonb_build_object('status',CASE WHEN (incoming->>'crawl_status'='error' OR incoming->>'blocked'='true') THEN CASE WHEN incoming->>'blocked'='true' THEN 'blocked' ELSE 'retry' END ELSE 'fetched' END,'recorded_at',clock_timestamp(),'lease_id',lease->>'id','evidence',jsonb_build_object('check','stored_source_fetch','identity_verified',false,'source_fingerprint',lease->>'fingerprint')),true)),updated_at=now() WHERE id=l.id;
  RETURN QUERY SELECT l.slug,true;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION zoi.listing_quality_state(l zoi.listings)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE visible boolean:=l.publish_status='published' AND l.moderation_status IN('clean','cleared') AND coalesce(l.marketplace_status,'')<>'hidden';
 source text:=coalesce(nullif(l.website,''),nullif(l.source_url,''),nullif(l.profile#>>'{_enrich,source_url}',''));fingerprint text:=zoi.listing_quality_fingerprint(l);task text;v jsonb;tasks jsonb:='{}';stored jsonb:=coalesce(l.profile->'_coverage','{}');
BEGIN
 FOREACH task IN ARRAY ARRAY['classification','enrichment','design','verification'] LOOP
  v:=jsonb_build_object('status',CASE WHEN NOT coalesce(visible,false) THEN 'blocked_visibility' WHEN source IS NULL THEN 'source_missing' WHEN task='enrichment' AND l.profile#>>'{_enrich,blocked}'='true' THEN 'blocked_existing' ELSE 'pending' END);
  IF coalesce(visible,false) AND source IS NOT NULL AND stored->>'fingerprint'=fingerprint AND stored#>>ARRAY['tasks',task,'status'] IN('verified','retry','blocked','fetched') AND (stored#>>ARRAY['tasks',task,'status']<>'verified' OR coalesce(zoi.enrich_timestamp(stored#>>ARRAY['tasks',task,'recorded_at']),'-infinity')>now()-interval '7 days') AND NOT(task='enrichment' AND coalesce(l.profile#>>'{_enrich,blocked}','false')='true') THEN v:=stored#>ARRAY['tasks',task];END IF;
  tasks:=tasks||jsonb_build_object(task,v);
 END LOOP;
 RETURN jsonb_build_object('version',1,'fingerprint',fingerprint,'public_eligible',coalesce(visible,false),'source_available',source IS NOT NULL,'source_kind',CASE WHEN source IS NULL THEN 'source_missing' WHEN source~*'/(profile|members?|directory|people|team|staff)(/|\?|$)' THEN 'member_or_directory' WHEN source~*'^https?://[^/]+/?$' THEN 'root_identity_unverified' ELSE 'source_identity_unverified' END,'owner_managed',l.owner_workspace_id IS NOT NULL,'tasks',tasks,'audit',CASE WHEN stored->>'fingerprint'=fingerprint THEN stored->'audit' ELSE NULL END);
END $function$

